H=Path(__file__).resolve().parent;R=H/'home_first_snapshot';meta=R/'VOLLEY_G5_ACR1_home.json';step=R/'VOLLEY_G5_ACR1_home.step';mb=meta.read_bytes();sb=step.read_bytes();m=json.loads(mb);before=hashlib.sha256(sb).hexdigest();start=time.perf_counter()
